import React from 'react';

const styles = {
  header: {
    backgroundColor: '#004d40', // A deep, professional green
    color: 'white',
    padding: '24px',
    borderBottom: '4px solid #00796b',
  },
  container: {
    maxWidth: '1200px',
    margin: '0 auto',
  },
  title: {
    fontSize: '2.5rem',
    fontWeight: 'bold',
    margin: 0,
  },
  subtitle: {
    fontSize: '1.25rem',
    marginTop: '4px',
    fontStyle: 'italic',
  },
  nav: {
    marginTop: '16px',
  },
  navLink: {
    color: 'white',
    textDecoration: 'none',
    marginRight: '24px',
    fontSize: '1.1rem',
  },
};

const Header = () => {
  return (
    <header style={styles.header}>
      <div style={styles.container}>
        <h1 style={styles.title}>Dietitian Pradeepa's Clinic</h1>
        <p style={styles.subtitle}>பரிபூரண ஆரோக்கியத்துடன் வாழ்க!</p>
        <nav style={styles.nav}>
          <a href="#home" style={styles.navLink}>Home</a>
          <a href="#about" style={styles.navLink}>About Us</a>
          <a href="#services" style={styles.navLink}>Services</a>
          <a href="#contact" style={styles.navLink}>Contact Us</a>
        </nav>
      </div>
    </header>
  );
};

export default Header;
